/// <summary>
/// This is an extension class for VendInvoicePurchLink table.
/// </summary>
[ExtensionOf(tableStr(VendInvoicePurchLink))]
final class METVendInvoicePurchLinkTable_Extension
{
}

Method.Source:
/// <summary>
/// Initializes the orig purch id for the claim invoice journal.
/// </summary>
/// <param name = "vendInvoiceJour">vendInvoiceJour</param>
void initFromVendInvoiceJour(VendInvoiceJour vendInvoiceJour)
{
    next initFromVendInvoiceJour(vendInvoiceJour);

    if (METVendParameters::find().EnableMetcashMatchingLogic && vendInvoiceJour.Qty < 0)
    {
        this.origPurchId = vendInvoiceJour.PurchId;
    }
}
